enum pipe_video_chroma_format {
   PIPE_VIDEO_CHROMA_FORMAT_400,
   PIPE_VIDEO_CHROMA_FORMAT_420,
   PIPE_VIDEO_CHROMA_FORMAT_422,
   PIPE_VIDEO_CHROMA_FORMAT_444,
   PIPE_VIDEO_CHROMA_FORMAT_440,
   PIPE_VIDEO_CHROMA_FORMAT_NONE,
};

static inline enum pipe_video_chroma_format
pipe_format_to_chroma_format(enum pipe_format format)
{
   switch(format) {
   case PIPE_FORMAT_Y8_400_UNORM:
      return PIPE_VIDEO_CHROMA_FORMAT_400;
   case PIPE_FORMAT_Y8_V8_U8_420_UNORM:
   case PIPE_FORMAT_Y8_U8_V8_420_UNORM:
   case PIPE_FORMAT_Y8_U8V8_420_UNORM:
   case PIPE_FORMAT_Y8_V8U8_420_UNORM:
   case PIPE_FORMAT_Y10_U10V10_420_UNORM:
   case PIPE_FORMAT_Y10X6_U10X6_V10X6_420_UNORM:
   case PIPE_FORMAT_Y12X4_U12X4_V12X4_420_UNORM:
   case PIPE_FORMAT_Y16_U16_V16_420_UNORM:
   case PIPE_FORMAT_X6Y10_X6U10X6V10_420_UNORM:
   case PIPE_FORMAT_X4Y12_X4U12X4V12_420_UNORM:
   case PIPE_FORMAT_Y16_U16V16_420_UNORM:
   case PIPE_FORMAT_Y10Y10Y10X2_U10V10U10X2V10U10V10X2_420_UNORM:
      return PIPE_VIDEO_CHROMA_FORMAT_420;
   case PIPE_FORMAT_U8Y8V8Y8_422_UNORM:
   case PIPE_FORMAT_V8Y8U8Y8_422_UNORM:
   case PIPE_FORMAT_Y8U8Y8V8_422_UNORM:
   case PIPE_FORMAT_Y8V8Y8U8_422_UNORM:
   case PIPE_FORMAT_Y8_V8_U8_422_UNORM:
   case PIPE_FORMAT_Y10_U10V10_422_UNORM:
   case PIPE_FORMAT_Y8_U8_V8_422_UNORM:
   case PIPE_FORMAT_Y8_U8V8_422_UNORM:
   case PIPE_FORMAT_Y10X6_U10X6_V10X6_422_UNORM:
   case PIPE_FORMAT_Y12X4_U12X4_V12X4_422_UNORM:
   case PIPE_FORMAT_Y16_U16_V16_422_UNORM:
   case PIPE_FORMAT_Y16_U16V16_422_UNORM:
   case PIPE_FORMAT_X6Y10X6U10X6Y10X6V10_422_UNORM:
   case PIPE_FORMAT_X4Y12X4U12X4Y12X4V12_422_UNORM:
   case PIPE_FORMAT_Y16U16Y16V16_422_UNORM:
      return PIPE_VIDEO_CHROMA_FORMAT_422;
   case PIPE_FORMAT_A8Y8U8V8_444_UNORM:
   case PIPE_FORMAT_X8Y8U8V8_444_UNORM:
   case PIPE_FORMAT_Y8_U8_V8_444_UNORM:
   case PIPE_FORMAT_Y10X6_U10X6_V10X6_444_UNORM:
   case PIPE_FORMAT_Y12X4_U12X4_V12X4_444_UNORM:
   case PIPE_FORMAT_Y16_U16_V16_444_UNORM:
   case PIPE_FORMAT_U10Y10V10A2_444_UNORM:
   case PIPE_FORMAT_X4U12X4Y12X4V12X4A12_444_UNORM:
   case PIPE_FORMAT_U16Y16V16A16_444_UNORM:
      return PIPE_VIDEO_CHROMA_FORMAT_444;
   case PIPE_FORMAT_Y8_U8_V8_440_UNORM:
      return PIPE_VIDEO_CHROMA_FORMAT_440;
   default:
      return PIPE_VIDEO_CHROMA_FORMAT_NONE;
   }
}

static inline enum pipe_format
util_format_get_plane_format(enum pipe_format format, unsigned plane)
{
   switch (format) {
   case PIPE_FORMAT_Y8_V8_U8_420_UNORM:
      return PIPE_FORMAT_R8_UNORM;
   case PIPE_FORMAT_Y8_V8_U8_422_UNORM:
      return PIPE_FORMAT_R8_UNORM;
   case PIPE_FORMAT_Y8_U8_V8_420_UNORM:
      return PIPE_FORMAT_R8_UNORM;
   case PIPE_FORMAT_Y8_U8V8_420_UNORM:
      return !plane ? PIPE_FORMAT_R8_UNORM : PIPE_FORMAT_RG88_UNORM;
   case PIPE_FORMAT_Y8_V8U8_420_UNORM:
      return !plane ? PIPE_FORMAT_R8_UNORM : PIPE_FORMAT_GR88_UNORM;
   case PIPE_FORMAT_R8_G8B8_420_UNORM:
      return !plane ? PIPE_FORMAT_R8_UNORM : PIPE_FORMAT_RG88_UNORM;
   case PIPE_FORMAT_R8_B8G8_420_UNORM:
      return !plane ? PIPE_FORMAT_R8_UNORM : PIPE_FORMAT_GR88_UNORM;
   case PIPE_FORMAT_G8_B8R8_420_UNORM:
      return !plane ? PIPE_FORMAT_R8_UNORM : PIPE_FORMAT_GR88_UNORM;
   case PIPE_FORMAT_R8_G8B8_422_UNORM:
      return !plane ? PIPE_FORMAT_R8_UNORM : PIPE_FORMAT_RG88_UNORM;
   case PIPE_FORMAT_R8_B8G8_422_UNORM:
      return !plane ? PIPE_FORMAT_R8_UNORM : PIPE_FORMAT_GR88_UNORM;
   case PIPE_FORMAT_G8_B8R8_422_UNORM:
      return !plane ? PIPE_FORMAT_R8_UNORM : PIPE_FORMAT_GR88_UNORM;
   case PIPE_FORMAT_R8_G8_B8_420_UNORM:
      return PIPE_FORMAT_R8_UNORM;
   case PIPE_FORMAT_R8_B8_G8_420_UNORM:
      return PIPE_FORMAT_R8_UNORM;
   case PIPE_FORMAT_G8_B8_R8_420_UNORM:
      return PIPE_FORMAT_R8_UNORM;
   case PIPE_FORMAT_R8_G8_B8_444_UNORM:
      return PIPE_FORMAT_R8_UNORM;
   case PIPE_FORMAT_X6G10_X6B10X6R10_420_UNORM:
      return !plane ? PIPE_FORMAT_X6R10_UNORM : PIPE_FORMAT_X6R10X6G10_UNORM;
   case PIPE_FORMAT_X4G12_X4B12X4R12_420_UNORM:
      return !plane ? PIPE_FORMAT_X4R12_UNORM : PIPE_FORMAT_X4R12X4G12_UNORM;
   case PIPE_FORMAT_Y8_U8_V8_422_UNORM:
      return PIPE_FORMAT_R8_UNORM;
   case PIPE_FORMAT_Y8_U8V8_422_UNORM:
      return !plane ? PIPE_FORMAT_R8_UNORM : PIPE_FORMAT_RG88_UNORM;
   case PIPE_FORMAT_Y8_U8_V8_444_UNORM:
      return PIPE_FORMAT_R8_UNORM;
   case PIPE_FORMAT_Y8_U8_V8_440_UNORM:
      return PIPE_FORMAT_R8_UNORM;
   case PIPE_FORMAT_Y10X6_U10X6_V10X6_420_UNORM:
      return PIPE_FORMAT_R16_UNORM;
   case PIPE_FORMAT_Y12X4_U12X4_V12X4_420_UNORM:
      return PIPE_FORMAT_R16_UNORM;
   case PIPE_FORMAT_Y16_U16_V16_420_UNORM:
      return PIPE_FORMAT_R16_UNORM;
   case PIPE_FORMAT_Y10X6_U10X6_V10X6_422_UNORM:
      return PIPE_FORMAT_R16_UNORM;
   case PIPE_FORMAT_Y12X4_U12X4_V12X4_422_UNORM:
      return PIPE_FORMAT_R16_UNORM;
   case PIPE_FORMAT_Y16_U16_V16_422_UNORM:
      return PIPE_FORMAT_R16_UNORM;
   case PIPE_FORMAT_Y10X6_U10X6_V10X6_444_UNORM:
      return PIPE_FORMAT_R16_UNORM;
   case PIPE_FORMAT_Y12X4_U12X4_V12X4_444_UNORM:
      return PIPE_FORMAT_R16_UNORM;
   case PIPE_FORMAT_Y16_U16_V16_444_UNORM:
      return PIPE_FORMAT_R16_UNORM;
   case PIPE_FORMAT_Y16_U16V16_422_UNORM:
      return !plane ? PIPE_FORMAT_R16_UNORM : PIPE_FORMAT_R16G16_UNORM;
   case PIPE_FORMAT_X6Y10_X6U10X6V10_420_UNORM:
      return !plane ? PIPE_FORMAT_X6R10_UNORM : PIPE_FORMAT_X6R10X6G10_UNORM;
   case PIPE_FORMAT_X4Y12_X4U12X4V12_420_UNORM:
      return !plane ? PIPE_FORMAT_X4R12_UNORM : PIPE_FORMAT_X4R12X4G12_UNORM;
   case PIPE_FORMAT_Y16_U16V16_420_UNORM:
      return !plane ? PIPE_FORMAT_R16_UNORM : PIPE_FORMAT_R16G16_UNORM;

   /* No matching per-plane RGB format, we return the original format in that case. */
   case PIPE_FORMAT_Y10_U10V10_420_UNORM:
   case PIPE_FORMAT_Y10_U10V10_422_UNORM:
   case PIPE_FORMAT_R10_G10B10_420_UNORM:
   case PIPE_FORMAT_R10_G10B10_422_UNORM:
   case PIPE_FORMAT_Y10Y10Y10X2_U10V10U10X2V10U10V10X2_420_UNORM:
   default:
      return format;
   }
}


static inline unsigned
util_format_get_plane_width(enum pipe_format format, unsigned plane,
                            unsigned width)
{
   if (!plane)
      return width;

   switch (format) {
   case PIPE_FORMAT_Y8_V8_U8_420_UNORM:
   case PIPE_FORMAT_Y8_V8_U8_422_UNORM:
   case PIPE_FORMAT_Y8_U8_V8_420_UNORM:
   case PIPE_FORMAT_Y8_U8V8_420_UNORM:
   case PIPE_FORMAT_Y8_V8U8_420_UNORM:
   case PIPE_FORMAT_Y10_U10V10_420_UNORM:
   case PIPE_FORMAT_Y10_U10V10_422_UNORM:
   case PIPE_FORMAT_R8_G8B8_420_UNORM:
   case PIPE_FORMAT_R8_B8G8_420_UNORM:
   case PIPE_FORMAT_G8_B8R8_420_UNORM:
   case PIPE_FORMAT_R8_G8B8_422_UNORM:
   case PIPE_FORMAT_R8_B8G8_422_UNORM:
   case PIPE_FORMAT_G8_B8R8_422_UNORM:
   case PIPE_FORMAT_R10_G10B10_420_UNORM:
   case PIPE_FORMAT_R10_G10B10_422_UNORM:
   case PIPE_FORMAT_R8_G8_B8_420_UNORM:
   case PIPE_FORMAT_R8_B8_G8_420_UNORM:
   case PIPE_FORMAT_G8_B8_R8_420_UNORM:
   case PIPE_FORMAT_X6G10_X6B10X6R10_420_UNORM:
   case PIPE_FORMAT_X4G12_X4B12X4R12_420_UNORM:
   case PIPE_FORMAT_Y8_U8_V8_422_UNORM:
   case PIPE_FORMAT_Y8_U8V8_422_UNORM:
   case PIPE_FORMAT_Y10X6_U10X6_V10X6_420_UNORM:
   case PIPE_FORMAT_Y12X4_U12X4_V12X4_420_UNORM:
   case PIPE_FORMAT_Y16_U16_V16_420_UNORM:
   case PIPE_FORMAT_Y10X6_U10X6_V10X6_422_UNORM:
   case PIPE_FORMAT_Y12X4_U12X4_V12X4_422_UNORM:
   case PIPE_FORMAT_Y16_U16_V16_422_UNORM:
   case PIPE_FORMAT_Y16_U16V16_422_UNORM:
   case PIPE_FORMAT_X6Y10_X6U10X6V10_420_UNORM:
   case PIPE_FORMAT_X4Y12_X4U12X4V12_420_UNORM:
   case PIPE_FORMAT_Y16_U16V16_420_UNORM:
   case PIPE_FORMAT_Y10Y10Y10X2_U10V10U10X2V10U10V10X2_420_UNORM:
      return DIV_ROUND_UP(width, 2);
   default:
      return width;
   }
}

static inline unsigned
util_format_get_plane_height(enum pipe_format format, unsigned plane,
                             unsigned height)
{
   if (!plane)
      return height;

   switch (format) {
   case PIPE_FORMAT_Y8_V8_U8_420_UNORM:
   case PIPE_FORMAT_Y8_U8_V8_420_UNORM:
   case PIPE_FORMAT_Y8_U8V8_420_UNORM:
   case PIPE_FORMAT_Y8_V8U8_420_UNORM:
   case PIPE_FORMAT_Y10_U10V10_420_UNORM:
   case PIPE_FORMAT_R8_G8B8_420_UNORM:
   case PIPE_FORMAT_R8_B8G8_420_UNORM:
   case PIPE_FORMAT_G8_B8R8_420_UNORM:
   case PIPE_FORMAT_R10_G10B10_420_UNORM:
   case PIPE_FORMAT_R8_G8_B8_420_UNORM:
   case PIPE_FORMAT_R8_B8_G8_420_UNORM:
   case PIPE_FORMAT_G8_B8_R8_420_UNORM:
   case PIPE_FORMAT_X6G10_X6B10X6R10_420_UNORM:
   case PIPE_FORMAT_X4G12_X4B12X4R12_420_UNORM:
   case PIPE_FORMAT_Y8_U8_V8_440_UNORM:
   case PIPE_FORMAT_Y10X6_U10X6_V10X6_420_UNORM:
   case PIPE_FORMAT_Y12X4_U12X4_V12X4_420_UNORM:
   case PIPE_FORMAT_Y16_U16_V16_420_UNORM:
   case PIPE_FORMAT_X6Y10_X6U10X6V10_420_UNORM:
   case PIPE_FORMAT_X4Y12_X4U12X4V12_420_UNORM:
   case PIPE_FORMAT_Y16_U16V16_420_UNORM:
   case PIPE_FORMAT_Y10Y10Y10X2_U10V10U10X2V10U10V10X2_420_UNORM:
      return DIV_ROUND_UP(height, 2);
   default:
      return height;
   }
}


